"""Golden file comparison used by the settlement desk's visible examples."""
import json
import os
from pathlib import Path
import tempfile


def read(path):
    return json.loads(Path(path).read_text(encoding="utf-8"))


def compare(expected, actual):
    differences = []
    if len(expected) != len(actual):
        differences.append(f"row count: expected {len(expected)}, got {len(actual)}")
    for i, (left, right) in enumerate(zip(expected, actual)):
        if left != right:
            differences.append(f"row {i}: expected {left!r}, got {right!r}")
    return differences


def record(path, rows):
    path = Path(path)
    with tempfile.NamedTemporaryFile(mode="w", dir=path.parent, encoding="utf-8",
                                     delete=False) as stream:
        temp = Path(stream.name)
        json.dump(rows, stream, indent=2)
        stream.write("\n")
    try:
        os.replace(temp, path)
    finally:
        temp.unlink(missing_ok=True)


def inspect_candidate(path, rows):
    try:
        approved = read(path)
    except ValueError:
        raise ValueError(f"approved table {path} is unreadable") from None
    return compare(approved, rows)


def reconciliation_context(golden, receipt=None):
    """Find the receipt for this table; receipt references are relative to it.

    Unrelated/custom tables without a receipt keep using their live inputs.
    An explicitly selected receipt must describe the selected golden table.
    """
    path = Path(receipt) if receipt is not None else Path(golden).with_name("receipt.json")
    if receipt is None and not path.exists():
        return None
    context = read(path)
    if (path.parent / context["table"]).resolve() != Path(golden).resolve():
        if receipt is not None:
            raise ValueError("receipt describes a different approved table")
        return None
    return (path.parent / context["case_order"],
            path.parent / context["calendar_edition"])


def order_cases(rows, order):
    """Put feed rows in signed approval order, rejecting ambiguous/incomplete feeds."""
    if not isinstance(order, list) or any(not isinstance(case, str) for case in order):
        raise ValueError("approval order must be an array of case IDs")
    if len(set(order)) != len(order):
        raise ValueError("duplicate case in approval order")
    indexed = {}
    for row in rows:
        case = row["case"]
        if not isinstance(case, str) or case in indexed:
            raise ValueError("invalid or duplicate feed case")
        indexed[case] = row
    if set(indexed) != set(order):
        raise ValueError("feed cases do not match approval order")
    return [indexed[case] for case in order]
